<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3'; import MemberLayout from '@/Layouts/MemberLayout.vue'; const props = defineProps({ invoice: Object }); const format = (value) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value); const form = useForm({ proof: null }); const upload = () => form.post(route('member.invoices.payments.store', props.invoice.id));
</script>
<template><Head title="Detail Tagihan"/><MemberLayout><Link :href="route('member.invoices.index')" class="text-sm font-semibold text-aski-700">← Kembali ke tagihan</Link><div class="card mt-6 max-w-2xl p-7"><p class="text-sm font-semibold text-aski-700">DETAIL TAGIHAN</p><h1 class="mt-1 text-3xl font-bold text-aski-900">{{ invoice.number }}</h1><div class="mt-7 grid gap-5 border-y border-slate-100 py-5 sm:grid-cols-2"><div><p class="text-sm text-slate-500">Nominal</p><p class="text-xl font-bold">{{ format(invoice.amount) }}</p></div><div><p class="text-sm text-slate-500">Status</p><span class="inline-block rounded-full bg-gold-100 px-3 py-1 text-xs font-semibold text-gold-600">{{ invoice.status === 'paid' ? 'Dibayar' : 'Belum dibayar' }}</span></div><div><p class="text-sm text-slate-500">Tanggal terbit</p><p>{{ invoice.issued_at }}</p></div><div><p class="text-sm text-slate-500">Jatuh tempo</p><p>{{ invoice.due_at }}</p></div></div><form v-if="invoice.status === 'unpaid' && !invoice.payments.some(payment => ['submitted', 'verified'].includes(payment.status))" class="mt-6" @submit.prevent="upload"><label class="text-sm font-semibold">Bukti pembayaran (PDF/JPG/PNG, maks. 5 MB)<input type="file" accept=".pdf,.jpg,.jpeg,.png" class="mt-2 block w-full text-sm" @input="form.proof = $event.target.files[0]"/></label><p class="text-xs text-red-600">{{ form.errors.proof }}</p><button class="btn-primary mt-4">Kirim Bukti</button></form><div v-for="payment in invoice.payments" :key="payment.id" class="mt-5 rounded-lg bg-slate-50 p-4 text-sm"><b>Status bukti: {{ payment.status }}</b><p v-if="payment.admin_note" class="mt-1">Catatan Admin: {{ payment.admin_note }}</p></div></div></MemberLayout></template>
